/**
 * Edu shared contracts.
 *
 * The core layer: every module may depend on these types and constants, and
 * this file depends on nothing. Which modules may import each other is the
 * layer table in docs/ARCHITECTURE.md §3 (enforced by a test). Changing a type
 * here is a cross-team decision owned by the lead.
 */

// ─── Second brain ────────────────────────────────────────────────────────────

/** The three memory layers plus the generated index. */
export type Tier = 'canonical' | 'episodic' | 'transitive';

/** Folder names on disk, Obsidian-friendly and sortable. */
export const TIER_DIRS: Record<Tier, string> = {
  canonical: '1-canonical',
  episodic: '2-episodic',
  transitive: '3-transitive',
};
export const INDEX_DIR = '0-index';

/**
 * Transitive items carry what moves forward between sessions.
 * Filename prefix: D- decision, H- hypothesis, C- commitment, L- lesson.
 */
export type TransitiveKind = 'decision' | 'hypothesis' | 'commitment' | 'lesson';
export const TRANSITIVE_PREFIX: Record<TransitiveKind, string> = {
  decision: 'D-',
  hypothesis: 'H-',
  commitment: 'C-',
  lesson: 'L-',
};

/** Canonical notes are grouped by domain folder. */
export type CanonicalKind = 'identity' | 'standard' | 'lexicon' | 'domain' | 'person' | 'preference';

/**
 * Claim band: how strongly a note may be asserted.
 * verified = backed by structured evidence; inferred = reasoned from evidence;
 * hypothesis = proposed, unproven. Edu never states a hypothesis as fact.
 */
export type ClaimBand = 'verified' | 'inferred' | 'hypothesis';

export type TransitiveStatus =
  // decision
  | 'active' | 'reverted'
  // hypothesis
  | 'open' | 'confirmed' | 'refuted' | 'no-evidence'
  // commitment
  | 'pending' | 'delivered' | 'overdue'
  // lesson
  | 'candidate' | 'proven' | 'retired';

/** Canonical writes need explicit human confirmation: proposed → accepted. */
export type CanonicalStatus = 'proposed' | 'accepted' | 'superseded';

/** Learning signal kept on lessons and canonical notes to drive self-improvement. */
export interface UsageStats {
  /**
   * Times the note was injected into context or recalled. Exposure (`uses`, `lastUsed`) lives in the machine-local
   * ledger (`<root>/.edu-local/usage.json`); reads merge it in. Values still found in frontmatter are legacy.
   */
  uses: number;
  /** Times feedback said it helped (advisory and verified; ranking signal only, never promotion proof). */
  wins: number;
  /** Times feedback said it misled or was irrelevant. */
  losses: number;
  /** ISO timestamp of last exposure (recall or context injection). Exposure is not confirmation. */
  lastUsed?: string;
  /** Distinct externally verified successful outcomes. Only these can promote a lesson. */
  verifiedWins?: number;
  /** Distinct externally verified failed outcomes. */
  verifiedLosses?: number;
  /** ISO timestamp of the last verified success; the recency of confirmation. */
  lastVerified?: string;
  /** Recent feedback event keys (`a:<eventId>` advisory, `v:<eventId>` verified), kept in full; makes feedback idempotent per event. */
  events?: string[];
}

/**
 * Context for `Brain.feedback`. Only trusted runtime callers (the orchestrator) may set `verified: true`,
 * and only for an outcome checked externally (e.g. deterministic verification). `eventId` identifies the
 * outcome (non-empty, at most 200 characters; `verified` must be the boolean `true`) so repeated feedback for the same event counts once. MCP callers are advisory and never verified.
 */
export interface FeedbackContext {
  eventId: string;
  verified: boolean;
  evidence?: string[];
}

export interface NoteMeta {
  id: string;            // stable slug, unique within the brain (e.g. "L-prefer-small-prs")
  tier: Tier;
  title: string;
  kind?: TransitiveKind | CanonicalKind | 'session';
  status?: TransitiveStatus | CanonicalStatus | 'open-session' | 'closed';
  band?: ClaimBand;
  tags: string[];
  links: string[];       // ids referenced as [[wikilinks]]
  created: string;       // ISO
  updated?: string;      // ISO
  source?: string;       // who/what wrote it: "user", "edu:reflect", "claude", "import:albert"…
  owner?: string;        // commitments
  stakeholder?: string;  // commitments: who the commitment is for (Albert `para`)
  due?: string;          // commitments, ISO date
  supersedes?: string;   // decision reverting another, canonical replacing another
  usage?: UsageStats;
  /** Decision reverted by a later one: the id of the decision that replaced it (set by importers). */
  superseded_by?: string;
  /** Other names the note answers to (Obsidian resolves `[[alias]]`; `edu_read` resolves them too). */
  aliases?: string[];
  /** The note's id in the system it was imported from (e.g. Albert `D-010`). */
  legacy_id?: string;
  /** Where an imported note came from, e.g. `albert:3-TRANSITIVO/decisiones/D-010_x.md`; makes re-import idempotent. */
  origin?: string;
  /** Source frontmatter kept verbatim when Edu has no field for it (Albert import). */
  albert?: Record<string, unknown>;
  /** Set by an importer when the source frontmatter could not be parsed; the raw source text is the body. */
  import_warning?: 'invalid-frontmatter';
  /** Provenance: machine that last wrote the note (defaults to `os.hostname()` on write). */
  host?: string;
  /** Provenance: agent that last wrote the note, e.g. `claude-code`, `codex`, `pi`, `opencode`, `antigravity`, `cli`. */
  agent?: string;
  /** Provenance: Edu session id the note was last written in. */
  session?: string;
}

/**
 * Who is writing a note (provenance). Every field is optional; `host` defaults to `os.hostname()`.
 * Recorded on the note as `host`/`agent`/`session` (undefined fields are omitted from frontmatter).
 */
export interface NoteOrigin {
  host?: string;
  agent?: string;
  session?: string;
}

export interface Note {
  meta: NoteMeta;
  body: string;          // markdown without frontmatter
  path: string;          // absolute path on disk
}

export interface RecallHit {
  note: Note;
  score: number;         // final rank score (relevance × learned weight)
  why: string;           // one line: matched terms / learned weight, for transparency
}

/** Where a brain lives. Project brains overlay the global brain. */
export interface BrainLocation {
  scope: 'global' | 'project';
  root: string;          // directory containing EDU.md, config.json and (by default) brain/
  /** Absolute brain folder when `.edu/config.json` sets `brainDir`; default `<root>/brain`. Read it through `brainPath()`. */
  brainDir?: string;
}

// ─── Context budget ──────────────────────────────────────────────────────────

export interface ContextRequest {
  query?: string;
  role?: string;
  /** Token budget for the whole pack. */
  budgetTokens: number;
}

export interface ContextSection {
  title: string;
  tokens: number;
  noteIds: string[];
  text: string;
}

export interface ContextPack {
  text: string;
  tokens: number;
  budgetTokens: number;
  sections: ContextSection[];
  /** Notes that matched but did not fit; reachable later via edu_recall/edu_read. */
  deferred: string[];
}

// ─── Evidence ────────────────────────────────────────────────────────────────

export type FailureType = 'context' | 'tool' | 'feedback' | 'verify' | 'recovery' | 'entropy' | 'model' | 'unknown';
export type OutcomeLabel = 'autonomous_verified_success' | 'assisted_verified_success' | 'unverified_success' | 'failed' | 'unsafe_invalid';
export type HarnessLevel = 'H0' | 'H1' | 'H2' | 'H3';

export interface Requirement { id: string; text: string }
export interface DeterministicCheck {
  id: string;
  requirementIds: string[];
  command: string;
  expect: { exitCode?: number; stdoutIncludes?: string };
  timeoutMs: number;
}

// ─── Engines (the CLIs Edu drives) ───────────────────────────────────────────

export type CliId = 'claude' | 'codex' | 'pi' | 'opencode' | 'agy';
/** Every supported agent CLI, in Edu's preference order. */
export const CLI_IDS: readonly CliId[] = ['claude', 'codex', 'pi', 'opencode', 'agy'];

export type Autonomy = 'readonly' | 'ask' | 'auto' | 'full';

export type CrewJobStatus = 'queued' | 'running' | 'awaiting-approval' | 'done' | 'failed' | 'cancelled';
export type CrewJobMode = 'headless' | 'pane';

/**
 * Who answered an approval gate. `policy`: an upstream `--yes`; `user`: a person at the in-process prompt
 * (terminal or TUI); `cli` / `deck`: a person through `edu crew approve` or the Edu Deck; `host-llm`: the host
 * agent through MCP. Only `user`, `cli` and `deck` are human decisions.
 */
export type ApprovalBy = 'policy' | 'user' | 'cli' | 'deck' | 'host-llm';
/** The channels a crew decision file may name (`policy` and `user` never write decision files). */
export type CrewDecisionBy = Extract<ApprovalBy, 'cli' | 'deck' | 'host-llm'>;
export const HUMAN_APPROVERS: readonly ApprovalBy[] = ['user', 'cli', 'deck'];

/** The approval gate a crew job is waiting on. A decision applies only when it names this `requestId`. */
export interface CrewApproval {
  /** Fresh random nonce per gate. */
  requestId: string;
  openedAt: string;
  title: string;
  /** Exact shell commands of unregistered checks this gate would authorize (human decisions only). */
  unregisteredChecks?: string[];
}

/** A durable unit of work dispatched to one external coding CLI. */
export interface CrewJob {
  id: string;
  cli: CliId;
  task: string;
  mode: CrewJobMode;
  cwd: string;
  autonomy: Autonomy;
  kind?: 'task' | 'orchestration';
  goal?: string;
  playbook?: string;
  orchestrationMode?: OrchestrationMode;
  harnessLevel?: HarnessLevel;
  /** Set only by a human CLI (`edu run --detach --yes`); never from MCP. */
  autoApprove?: boolean;
  /** Set only by a human CLI (`--allow-unregistered-checks`): run planner-proposed checks without a human gate. */
  allowUnregisteredChecks?: boolean;
  /** Present while `status` is `awaiting-approval`. */
  approval?: CrewApproval;
  outcome?: OutcomeLabel;
  specPath?: string;
  verificationSummary?: string;
  status: CrewJobStatus;
  pid?: number;
  paneId?: string;
  agentName?: string;
  createdAt: string;
  endedAt?: string;
  summary: string;
  usage: Usage;
  note?: string;
  /** Prompt not yet delivered because the agent is waiting on a human answer (trust, login…) in its pane. */
  pendingPrompt?: string;
  /** Set once the pane agent was seen working, so a later idle means the turn finished. */
  observedWorking?: boolean;
  /** herdr `state_change_seq` right after the prompt was delivered; a later idle with a higher seq means done. */
  promptSeq?: number;
  /** Hash of the pane text right after the prompt; changed text plus idle means the agent answered. */
  promptPaneHash?: string;
  promptedAt?: string;
  /** Headless task jobs stop after this many minutes (default 60, or `crew.timeoutMinutes` in config.json). */
  timeoutMinutes?: number;
}

export interface EngineRunRequest {
  cli: CliId;
  prompt: string;
  cwd: string;
  systemPrompt?: string;
  model?: string;
  autonomy: Autonomy;
  resumeSessionId?: string;
  signal?: AbortSignal;
  /** Require host-enforced readonly; ordinary autonomy requests remain compatible. */
  requireReadonly?: boolean;
  /** No current adapter provides an Edu OS/network sandbox. */
  requireSandbox?: boolean;
  /** IDs must be unique per actual call; replay reuses receipts, never a new invocation with the same ID. */
  invocation?: { id: string; purpose: InvocationPurpose };
}

export type InvocationPurpose = 'task' | 'planning' | 'recovery' | 'reflection' | 'selection' | 'review' | 'chat' | 'extraction';
export type UsageField = 'inputTokens' | 'outputTokens' | 'cacheReadTokens' | 'cacheWriteTokens' | 'costUsd';

export interface Usage {
  /** Explicit true means complete reported measurement. Absent metadata is unknown. */
  known?: Partial<Record<UsageField, boolean>>;
  /** Provider observations before adapter normalization; never summed into totals. */
  raw?: Partial<Record<UsageField, number>>;
  inputSemantics?: 'inclusive-cache' | 'exclusive-cache' | 'unknown';
  /** Lifecycle markers carry no token/cost delta; only normal completion supersedes pending. */
  receipt?: 'pending' | 'complete';
  observationId?: string;
  invocationId?: string;
  purpose?: InvocationPurpose;
  /** Aggregate bookkeeping, persisted for replay deduplication. */
  observationIds?: string[];
  observations?: number;
  /** Aggregate lifecycle and intrinsic knownness, retained so later completion can resolve pending calls. */
  invocationStates?: Record<string, 'pending' | 'complete'>;
  observedKnown?: Partial<Record<UsageField, boolean>>;
  /** Normalized total input, including cache subsets. Numeric placeholders require knownness. */
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens?: number;
  cacheWriteTokens?: number;
  /** USD, when the engine reports it; undefined when unknown (never guessed). */
  costUsd?: number;
}

/**
 * Normalized event stream. Every engine adapter maps its native JSONL into
 * these events; the orchestrator adds agent.* events; the TUI renders them;
 * runs are persisted as JSONL of EduEvent for replay.
 */
export type EduEvent =
  | { type: 'run.start'; runId: string; goal: string; mode: OrchestrationMode; at: string }
  | { type: 'run.end'; runId: string; ok: boolean; summary: string; at: string }
  /** What the user typed in the home view, before Edu routes it to chat or a task. */
  | { type: 'chat.user'; text: string; at: string }
  | { type: 'agent.spawn'; agentId: string; parentId?: string; role: RoleId; cli: CliId; model?: string; task: string; at: string }
  | { type: 'agent.status'; agentId: string; status: AgentStatus; at: string }
  | { type: 'agent.text'; agentId: string; text: string; at: string }
  | { type: 'agent.thinking'; agentId: string; text: string; at: string }
  | { type: 'tool.call'; agentId: string; callId: string; tool: string; input: string; at: string }
  | { type: 'tool.result'; agentId: string; callId: string; ok: boolean; output: string; at: string }
  /** Usage is a DELTA for this turn/step; consumers sum per agent and per run. */
  | { type: 'usage'; agentId: string; usage: Usage; at: string }
  /** Context-window occupancy snapshot (not a delta), when the engine or Edu can measure it. */
  | { type: 'context.usage'; agentId?: string; usedTokens: number; windowTokens: number; at: string }
  | { type: 'approval.request'; agentId: string; approvalId: string; title: string; detail: string; unregisteredChecks?: string[]; at: string }
  | { type: 'approval.resolve'; approvalId: string; approved: boolean; by: ApprovalBy; at: string }
  | { type: 'brain.recall'; agentId?: string; noteIds: string[]; at: string }
  | { type: 'brain.learn'; noteId: string; kind: TransitiveKind | 'canonical-proposal' | 'episode'; title: string; at: string }
  | { type: 'agent.end'; agentId: string; ok: boolean; summary: string; sessionId?: string; at: string }
  | { type: 'error'; agentId?: string; message: string; at: string }
  | { type: 'task.define'; requirements: Requirement[]; successCriteria?: string[]; at: string }
  | { type: 'spec.ready'; path: string; requirements: Requirement[]; checks: DeterministicCheck[]; steps: Array<{ id: string; role: string; cli: CliId; task: string }>; at: string }
  | { type: 'context.trace'; noteId: string; contribution: string; influenced: boolean; at: string }
  | { type: 'verify.result'; checkId?: string; method?: string; requirementIds: string[]; ok: boolean; output: string; exitCode?: number | null; durationMs?: number; timedOut?: boolean; kind: 'reproduction' | 'deterministic' | 'targeted-test' | 'regression' | 'lint' | 'review'; at: string }
  | { type: 'failure.attribution'; observed: string; expected: string; failureType: FailureType; evidence: string[]; alternatives: string[]; next: string; at: string }
  | { type: 'intervention'; by: 'user'; action: string; detail?: string; avoidable: boolean; harnessGap: FailureType; at: string }
  | { type: 'entropy.finding'; category: string; severity: 0 | 1 | 2 | 3; path: string; detail: string; at: string }
  | { type: 'outcome'; label: OutcomeLabel; metrics: Record<string, unknown>; at: string };

export type AgentStatus = 'queued' | 'running' | 'awaiting-approval' | 'done' | 'failed' | 'cancelled';

export interface EngineCapabilities {
  readonly: 'enforced' | 'unsupported';
  mechanism?: string;
  isolation: 'host';
  limitations: string[];
}

export interface Engine {
  readonly capabilities?: EngineCapabilities;
  readonly cli: CliId;
  /** True when the CLI binary is installed and runnable. */
  available(): Promise<boolean>;
  /** Streams normalized events for one headless run. `agentId` is stamped on every event. */
  run(req: EngineRunRequest, agentId: string): AsyncIterable<EduEvent>;
}

// ─── Orchestration ───────────────────────────────────────────────────────────

/** Built-in roles. Users can add more under agents/. */
export type RoleId = 'lead' | 'explorer' | 'builder' | 'reviewer' | (string & {});

/**
 * solo  = one CLI plays every role (each role is still its own session, so
 *         explorers/reviewers can run in parallel even with a single LLM).
 * crew  = roles mapped to different CLIs; reviewers prefer a different vendor
 *         than the builder they review.
 */
export type OrchestrationMode = 'solo' | 'crew';

export interface RoleSpec {
  id: RoleId;
  title: string;
  icon: string;          // single glyph used by the TUI
  mission: string;
  autonomy: Autonomy;
  cli?: CliId;           // crew mode mapping
  model?: string;
}

export type ApprovalPolicy = 'always-ask' | 'ask-on-write' | 'auto';

/** Language of messages, generated pages and the TUI. */
export type Lang = 'en' | 'es';

export interface EduConfig {
  version: 1;
  mode: OrchestrationMode;
  defaultCli: CliId;
  playbook?: string;
  roles: RoleSpec[];
  approvals: ApprovalPolicy;
  context: { budgetTokens: number };
  /** Explicit routes override solo/crew heuristics; unavailable routes fail closed. */
  routing?: Partial<Record<'executor' | 'advisor' | 'reviewer', { cli: CliId; model?: string }>>;
  execution?: { maxSpawns: number; maxConcurrency: number; timeoutMs: number; maxAdvisorCalls: number };
  brain: { obsidianVault?: string };
  lang: Lang;
  /** Brain folder relative to the workspace root (the folder holding `.edu/`). Default `.edu/brain`. */
  brainDir?: string;
  /** Where `edu create` keeps copies of the original documents, relative to the workspace root. */
  sourcesDir?: string;
  /** The workspace agent's identity (e.g. "Albert"), used by briefs and identity injection. */
  identity?: WorkspaceIdentity;
  /**
   * Crew settings. The safety settings (`maxAutonomy`, `env`) are read only from the global config
   * (`EDU_HOME/config.json`), never from a project `.edu/config.json`, which an agent or a cloned repository
   * can write. `timeoutMinutes` is a dispatch default and may come from either.
   */
  crew?: CrewSettings;
}

export interface CrewSettings {
  /**
   * The crew autonomy ceiling. Default `auto`; only a person raises it (to `full`) in the global config.
   * - An MCP caller cannot request a crew job above it.
   * - An orchestration in a project brain runs any role from the project config or a playbook that asks for
   *   more with the ceiling instead, and records that as a limitation of the run.
   */
  maxAutonomy?: Autonomy;
  /** Extra environment variable names passed to agent CLIs on top of the built-in allowlist. */
  env?: { passthrough?: string[] };
  /** Default crew job timeout in minutes (1–1440; built-in default 60). */
  timeoutMinutes?: number;
}

export interface WorkspaceIdentity { name: string; role?: string; tone?: string; summary?: string }

// ─── CLI integration (installer) ─────────────────────────────────────────────

export type InstallScope = 'project' | 'global';

/** One file operation the installer performs; recorded in the manifest for uninstall. */
export interface InstallAction {
  cli: CliId;
  kind: 'managed-block' | 'file' | 'json-merge' | 'toml-merge' | 'symlink';
  path: string;
  description: string;
  /** Content hash after write, to detect user edits before uninstall. */
  sha256?: string;
  /** Previous content backup path for non-block writes. */
  backup?: string;
}

export interface InstallManifest {
  version: 1;
  eduVersion: string;
  installedAt: string;
  scope: InstallScope;
  actions: InstallAction[];
}

export interface CliIntegration {
  readonly cli: CliId;
  detect(): Promise<boolean>;
  /** Pure planning step: what would change. Used by --dry-run and tests. */
  plan(scope: InstallScope, root: string): Promise<InstallAction[]>;
  apply(actions: InstallAction[]): Promise<InstallAction[]>;
}
